import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

# Inline CUDA/C++ source code for custom kernels
extension_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ __forceinline__ float gelu_approx(float x) {
    // Approximate GELU (using the Tanh formulation or a simple approx)
    // 0.5 * x * (1 + erf(x / sqrt(2))) could be used. We'll do a simpler version here.
    const float sqrt_2 = 1.41421356237f;
    return 0.5f * x * (1.0f + erff(x / sqrt_2));
}

// 1) Custom GEMM kernel (naive) for (batch_size, in_features) x (out_features, in_features)^T
//    So out is (batch_size, out_features).
//    out[m, n] = sum_k( x[m, k] * weight[n, k] ) + bias[n]
__global__ void custom_gemm_kernel(const float* __restrict__ x,
                                   const float* __restrict__ weight,
                                   const float* __restrict__ bias,
                                   float* __restrict__ out,
                                   int batch_size, int in_features, int out_features) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;     // row in "out"
    int col = blockIdx.y * blockDim.y + threadIdx.y;     // column in "out"

    if (row < batch_size && col < out_features) {
        float val = 0.0f;
        for (int k = 0; k < in_features; k++) {
            val += x[row * in_features + k] * weight[col * in_features + k];
        }
        val += bias[col];
        out[row * out_features + col] = val;
    }
}

torch::Tensor custom_gemm_cuda(torch::Tensor x,
                               torch::Tensor weight,
                               torch::Tensor bias) {
    // x: (batch_size, in_features)
    // weight: (out_features, in_features)
    // bias: (out_features)
    // returns: (batch_size, out_features)
    int batch_size = x.size(0);
    int in_features = x.size(1);
    int out_features = weight.size(0);

    auto options = x.options();
    auto out = torch::zeros({batch_size, out_features}, options);

    dim3 block(16,16);
    dim3 grid((batch_size + block.x - 1) / block.x,
              (out_features + block.y - 1) / block.y);

    custom_gemm_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        in_features,
        out_features
    );
    return out;
}

// 2) Rowwise max: assume x is (N, O). We produce (N,1).
__global__ void rowwise_max_kernel(const float* __restrict__ x,
                                   float* __restrict__ out,
                                   int N,
                                   int O) {
    // each row in its own block, if possible
    int row = blockIdx.x;
    if (row < N) {
        float max_val = -FLT_MAX;
        for(int j = threadIdx.x; j < O; j += blockDim.x) {
            float val = x[row * O + j];
            if (val > max_val) {
                max_val = val;
            }
        }
        // reduce within the block
        __shared__ float sdata[256];
        int tid = threadIdx.x;
        sdata[tid] = max_val;
        __syncthreads();

        // parallel reduction
        for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
            if (tid < offset) {
                if (sdata[tid + offset] > sdata[tid]) {
                    sdata[tid] = sdata[tid + offset];
                }
            }
            __syncthreads();
        }

        // first thread in block writes out
        if (tid == 0) {
            out[row] = sdata[0];
        }
    }
}

torch::Tensor rowwise_max_cuda(torch::Tensor x) {
    // x: (N, O)
    // returns: (N, 1)
    int N = x.size(0);
    int O = x.size(1);
    auto out = torch::zeros({N, 1}, x.options());

    // we launch N blocks, each up to 256 threads for reduction
    int threads = 256;
    rowwise_max_kernel<<<N, threads>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        N,
        O
    );
    return out;
}

// 3) Subtract mean along dim=1 (but shape is (N,1), so it's trivial)
__global__ void sub_mean_kernel(const float* __restrict__ x,
                                float* __restrict__ out,
                                int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N) {
        // shape is (N,1), so the "mean" of row i is just x[i].
        // out[i] = x[i] - x[i] = 0
        float val = x[idx];
        float mean_val = val;
        out[idx] = val - mean_val;
    }
}

torch::Tensor sub_mean_cuda(torch::Tensor x) {
    // x: (N, 1)
    // returns: (N, 1)
    int N = x.size(0);
    auto out = torch::zeros_like(x);

    int block_size = 256;
    int grid_size = (N + block_size - 1) / block_size;
    sub_mean_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        N
    );
    return out;
}

// 4) GELU elementwise for (N,1)
__global__ void gelu_kernel(const float* __restrict__ x,
                            float* __restrict__ out,
                            int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        out[idx] = gelu_approx(val);
    }
}

torch::Tensor gelu_cuda(torch::Tensor x) {
    // x: (N,1)
    // returns: (N,1)
    int size = x.numel();
    auto out = torch::zeros_like(x);

    int block_size = 256;
    int grid_size = (size + block_size - 1) / block_size;
    gelu_kernel<<<grid_size, block_size>>>(x.data_ptr<float>(),
                                           out.data_ptr<float>(),
                                           size);
    return out;
}

''';

# Compile the custom extension
custom_ops = load_inline(
    name="custom_kernels_ext",
    cpp_sources="TORCH_LIBRARY(custom_kernels_ext, m) { }",  # minimal valid C++ content
    cuda_sources=extension_source,
    functions=[
        "custom_gemm_cuda",
        "rowwise_max_cuda",
        "sub_mean_cuda",
        "gelu_cuda"
    ],
    verbose=False
)

# Optimized Model
class ModelNew(nn.Module):
    """
    Optimized model that replaces GEMM, max, subtraction, and GELU with custom CUDA kernels.
    """
    def __init__(self, in_features, out_features, max_dim):
        super(ModelNew, self).__init__()
        # Store dimension info
        self.in_features = in_features
        self.out_features = out_features
        self.max_dim = max_dim
        # Create parameters similar to nn.Linear
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        self.bias = nn.Parameter(torch.randn(out_features))

    def forward(self, x):
        # 1) Custom GEMM
        x = custom_ops.custom_gemm_cuda(x, self.weight, self.bias)
        # 2) Rowwise max (dim=1 -> shape becomes (N,1) )
        x = custom_ops.rowwise_max_cuda(x)
        # 3) Subtract mean along dim=1
        x = custom_ops.sub_mean_cuda(x)
        # 4) GELU
        x = custom_ops.gelu_cuda(x)
        return x
